package com.vignesh.focuslist.ui.component

import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

/**
 * The Upcoming mascot: a dachshund sitting up, watching a ball it has not been
 * thrown yet.
 *
 * Waiting rather than resting, which is the difference between this screen and
 * Today. Something is coming, and the dog can see it.
 *
 * Exported from the board, node `879:6029`. The artwork fills its frame, so
 * unlike the other two it needs no offset. [MascotImage] explains why the paths
 * are built in Kotlin, and which colour role each tone takes.
 */
@Composable
internal fun UpcomingMascot(modifier: Modifier = Modifier) {
    MascotImage(
        width = MascotWidth,
        height = MascotHeight,
        modifier = modifier,
        build = ::dogWatchingABall
    )
}

private const val MascotWidth = 180f
private const val MascotHeight = 166.992f

private fun dogWatchingABall(pale: Color, body: Color, detail: Color): ImageVector =
    ImageVector.Builder(
        name = "UpcomingDogWatchingABall",
        defaultWidth = MascotWidth.dp,
        defaultHeight = MascotHeight.dp,
        viewportWidth = MascotWidth,
        viewportHeight = MascotHeight
    )
        .addPath(
            pathData = addPathNodes(GroundShadow),
            fill = SolidColor(pale)
        )
        .addPath(
            pathData = addPathNodes(Body),
            fill = SolidColor(body)
        )
        .addPath(
            pathData = addPathNodes(Chest),
            fill = SolidColor(pale)
        )
        .addPath(
            pathData = addPathNodes(Ear),
            fill = SolidColor(detail)
        )
        .addPath(
            pathData = addPathNodes(Tail),
            fill = SolidColor(detail)
        )
        .addPath(
            pathData = addPathNodes(PawFront),
            fill = SolidColor(detail)
        )
        .addPath(
            pathData = addPathNodes(PawBack),
            fill = SolidColor(detail)
        )
        .addPath(
            pathData = addPathNodes(Nose),
            fill = SolidColor(detail)
        )
        .addPath(
            pathData = addPathNodes(Eye),
            fill = SolidColor(detail)
        )
        .addPath(
            pathData = addPathNodes(Ball),
            fill = SolidColor(pale)
        )
        .build()

